#!/usr/bin/env python3
"""руки.md прогону: позиція → рука для кожного збирання, складена з запису звернень до моделі (`руки_із_запису.py`) і
звірена з тим, що записав стенд зі сторінки (`руки.jsonl`: позиція, рука, сід). Запуск із теки стенд/: python3 руки_md.py > ../руки.md"""
import glob, os, json, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from руки_із_запису import зіставити
print("# Руки образів у прогоні «Живий-як-людина-2»\n")
print("Рука кожного образу на екрані — з **запису звернень до моделі** (`стенд/службове/<с>/обміни.jsonl.gz`), незалежно від поля «рука», яке пише стенд (`руки_із_запису.py`): прозові руки 3 і 4 — виклик «personal stylist» з `person` (3) чи без нього (4), позиція — за назвами речей українською з виклику-перекладу; каталожні 1–2 — виклики «Build outfits», рука 2 — збірка зі слідом поломки в запиті (інші правила `task`, `statement_codes.volume_top_and_bottom_no_anchor` замість `volume_anchor`, зайвий ключ `kinds_missing`), позиція — за (слот, ціна) речей вибраного образу виклику «Choose one». Сід: ключ позицій = `перемішатиП(['1','2','3','4'], сід)` (`джерела/показ/стадії_збирання.js`), перераховано тут. Руки 3–4 без фото, цін і крамниць — задум (`аудит/ПРОДУКТ.md`, п.1).\n")
print("| ситуація · прохід | сід | ключ стенда / ключ із сіду | поз. 1 (стенд=запис) | поз. 2 | поз. 3 | поз. 4 | збіг |\n|---|---|---|---|---|---|---|---|")
разом = [0, 0]
for т in sorted(glob.glob("службове/*/обміни.jsonl*")):
    с = os.path.basename(os.path.dirname(т))
    for н, п in enumerate(зіставити(os.path.dirname(т)), 1):
        збіг = sum(1 for x in п['позиції'] if x['рука_стенда'] == x['рука_із_запису']) if п['ключ_стенда'] == п['ключ_із_сіду'] else 0
        разом[0] += збіг; разом[1] += 4
        print(f"| {с.split('_')[0]} · {н} | {п['сід']} | {п['ключ_стенда']} / {п['ключ_із_сіду']} | " + " | ".join(f"{x['рука_стенда']}={x['рука_із_запису']}" for x in п['позиції']) + f" | {збіг} з 4 |")
print(f"\nРазом: {разом[0]} з {разом[1]} позицій збіглося.")
